result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/paginate.test.mjs", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { paginate } from './paginate.mjs';

function makeItems(n) {
  return Array.from({ length: n }, (_, i) => i + 1);
}

test('25 items with perPage 10 gives pages of 10, 10, 5', () => {
  const items = makeItems(25);
  assert.deepEqual(paginate(items, 1, 10), items.slice(0, 10));
  assert.deepEqual(paginate(items, 2, 10), items.slice(10, 20));
  assert.deepEqual(paginate(items, 3, 10), items.slice(20, 25));
});

test('page 1 starts at the first item', () => {
  const items = ['a', 'b', 'c'];
  assert.deepEqual(paginate(items, 1, 2), ['a', 'b']);
});

test('page beyond the end returns []', () => {
  const items = makeItems(5);
  assert.deepEqual(paginate(items, 4, 10), []);
});

test('perPage 1 works', () => {
  const items = makeItems(3);
  assert.deepEqual(paginate(items, 1, 1), [1]);
  assert.deepEqual(paginate(items, 2, 1), [2]);
  assert.deepEqual(paginate(items, 3, 1), [3]);
});

test('invariant: concatenating all pages reconstructs the original array', () => {
  for (let trial = 0; trial < 50; trial++) {
    const total = Math.floor(Math.random() * 12); // sizes 0..11 (dozen random sizes)
    const perPage = Math.floor(Math.random() * 12) + 1;
    const items = Array.from({ length: total }, (_, i) => `item-${i}`);
    const pageCount = Math.max(1, Math.ceil(total / perPage));
    const pages = [];
    for (let page = 1; page <= pageCount; page++) {
      pages.push(...paginate(items, page, perPage));
    }
    assert.deepEqual(pages, items);
  }
});
"})
print(result)

